import java.util.*;

public class Main {
    static class Account {
        double balance;
        void deposit(double amount) { if (amount > 0) balance += amount; }
        void withdraw(double amount) { if (amount > 0 && amount <= balance) balance -= amount; }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        Map<Integer, Account> accounts = new HashMap<>();
        while (sc.hasNext()) {
            String cmd = sc.next();
            if (cmd.equals("end")) break;
            int id = sc.nextInt();
            if (cmd.equals("open")) accounts.put(id, new Account());
            else if (cmd.equals("balance")) System.out.printf(Locale.ROOT, "%.2f%n", accounts.get(id).balance);
            else {
                double amount = sc.nextDouble();
                Account account = accounts.get(id);
                if (cmd.equals("deposit")) account.deposit(amount);
                else account.withdraw(amount);
            }
        }
    }
}

