            if (Character.isUpperCase(c)) upper = true;
        }
        boolean ok = true;
        if (p.length() < 8) { System.out.println("Too short"); ok = false; }
        if (!digit) { System.out.println("No digit"); ok = false; }
        if (!upper) { System.out.println("No uppercase"); ok = false; }
        if (ok) System.out.println("OK");
    }
}

